data.query:
query Query($wherePH: OperatorHistoryWhereInput) {
  operatorHistory(where: $wherePH, orderBy: {field: occurAt, direction:desc}, first: 1) {
    edges {
      node {
        occurAt
        transactionTypeId
      }
    }
  }
  operatorHistory(where: $where)
}

query Query($where: ProductionSetupOutputWhereInput!, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String, $whereP:InventoryWhereInput, $wherePH: ProductionHistoryWhereInput) {
  output:productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        producedQuantity
        scrappedQuantity
        unitPerCycle
        standardPackQuantity
        remainingBalance
        virtual
        product {
          id
          customData
        }
        productionSetup {
          id
          mode {
            id 
            modeType {
              production
              changeover
            }
          }
          eventId
          operators(
          where: {
            operatorActivity: {
              includeLabor: {
                _eq:true      
              }
            }
          }
        ) {
            total
            edges {
              node {
                employeeId
                laborWeight
              }
            }
          }
        }
        workcenter {
          code
          id
          name
          shiftGroupId
          locationId
        }

        card:kanbanCard {
          id
          number
          cardQuantity
          currentQuantity
          productionHistories(where:$wherePH, orderBy: {field: occurAt, direction:desc}, first:1) {
            edges {
              node {
                occurAt
              }
            }
          }
          rack:kanbanRack{ 
            id
            number
            productStrategyProcess{ 
              code
              setupOperators
              productionOperators
              standardRate
              standardRate
              idealRate
              setupRate
              transferSerial


            id
            final
            productStrategy {
              id
              productId
              inventoryUnitId
              strategyProcesses {
                edges {
                  node {
                    id order
                  }
                }
              }
            }
            wip
            finishedGood
            unitWeight
            weightUnitId
            lotControl {
              beginProcessId
              autoLotNumber
            }

            productionType{
              id
              byProduct
              cell
              disassembly

              outside
              packaging
              production

              rework
            }
          }
        }
      }
        setupBoms{edges{node{id}}}
        standardBoms:setupBoms(where: {

            consumptionMode: {
              transferSerial: {
                _eq:false
              }
            }

        }) {

          edges {
            node {
              standardUsage
              minimumUsage
              maximumUsage
              componentProductStrategyProcessId
              componentProduct {id code}
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }

            }
          }
        }
        serialBoms:setupBoms(where: {

            consumptionMode: {
              transferSerial: {
                _eq:true
              }
            }

        }) {

          edges {
            node {
              standardUsage
              componentProductStrategyProcessId
              componentProduct{id code}
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }

            }
          }
        }
        updatedAt
      }
    }
  }
  partial:inventory(where:$whereP){
    edges {
      node {
        id
        grossWeight
        netWeight
        tareWeight
        theoreticalWeight
        active
        quantity {
          value
          unitId
        }
        inventoryStatusId
        inventoryTypeId
        locationId
        lotId
        masterInventoryId
        packagingMaterialId
        productId
        productStrategyProcessId
        weightUnitId
        workOrderId
        workOrderProcessId
      }
    }
}
}

