query getProductStrategy($where:ProductStrategyWhereInput){
  productStrategy(where:$where)
  {
    edges{node {id code strategyProcesses{
          edges{node{id code assemblyBoms{
              edges{node{id order componentProductId standardUsage}} } }} } }}
  }
  }

data.transform:
(

$ps := productStrategy.edges[0].node;
$psId := $cuid();

/* Setup product strategy */
$psPayload := $merge([$omit($ps,['strategyProcesses', 'product']),{
  "id": $psId,
  "productId": $ps.product.id
}]).{
  "create": $
};


$payloads:= $ps.strategyProcesses.edges.node.(
  $currentProcess := $;
  $pid := $cuid();
  {
    /* Setup product strategy <- strategy processes */
    "psPayload": $merge([$omit($currentProcess,['assemblyBoms']), {
      "id": $pid,
      "productStrategyId": $psId
    }]).{
      "create": $
    },
    /* Setup strategy processes <- BOM */
    "bomPayload": $merge([$currentProcess.assemblyBoms.edges.node, {
      "componentProductStrategyProcessId": $pid,
      "componentProductStrategyId": $psid
    }]).{
      "create": $
    } 
  }

);

{
  "psPayload": [$psPayload],
  "pspPayload": [$payloads.psPayload],
  "bomPayload": [$payloads.bomPayload]
};

)

